@import "../../styles/tokens.css";

@layer components {
  .feed-page-wrapper {
    background-color: var(--shelf-feed-page-bgColor-wrapper);
    max-width: var(--shelf-maxWidth-content);
  }

  .feed-page-heading {
    color: var(--shelf-feed-page-fgColor-heading);
    font-size: var(--shelf-font-size-2xl);
    font-weight: var(--shelf-font-weight-bold);
    line-height: var(--shelf-line-height-tight);
  }

  .feed-page-list {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-4);
  }

  .feed-item-card {
    background-color: var(--shelf-feed-page-bgColor-card);
    border: 1px solid var(--shelf-feed-page-borderColor-card);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-4);
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-2);
  }

  .feed-item-title {
    color: var(--shelf-feed-page-fgColor-title);
    font-size: var(--shelf-font-size-lg);
    font-weight: var(--shelf-font-weight-medium);
    line-height: var(--shelf-line-height-tight);
  }

  .feed-item-description {
    color: var(--shelf-feed-page-fgColor-description);
    font-size: var(--shelf-font-size-sm);
    line-height: var(--shelf-line-height-base);
  }
}
